## Building a Collection Utilities Module

### Generic Collection Operations

```xiom
mod coll_utils {
  pub fn find_max[T](items: &Vec[T], greater: fn(&T, &T) -> Bool) -> Option[T] {
    if items.len() == 0 { return Option.None; };
    let mut max_idx = 0;
    let mut i = 1;
    while i < items.len() {
      if greater(items.get(i).unwrap(), items.get(max_idx).unwrap()) {
        max_idx = i;
      };
      i += 1;
    };
    Option.Some(items.get(max_idx).unwrap().clone())
  }

  pub fn count_if[T](items: &Vec[T], predicate: fn(&T) -> Bool) -> Int {
    let mut count = 0;
    let mut i = 0;
    while i < items.len() {
      if predicate(items.get(i).unwrap()) {
        count += 1;
      };
      i += 1;
    };
    count
  }

  pub fn sum[T](items: &Vec[T], get_value: fn(&T) -> Int) -> Int {
    let mut total = 0;
    let mut i = 0;
    while i < items.len() {
      total += get_value(items.get(i).unwrap());
      i += 1;
    };
    total
  }
}
```

