use xiom.io;
module coll_utils {
  pub fn find_min[T](items: &Vec[T], less: fn(&T, &T) -> Bool) -> Option[T] {
    if items.len() == 0 { return None; };
    var min_idx = 0;
    var i = 1;
    while i < items.len() {
      if less(items.get(i).unwrap(), items.get(min_idx).unwrap()) {
        min_idx = i;
      };
      i += 1;
    };
    Some(items.get(min_idx).unwrap().clone())
  }

  pub fn all_of[T](items: &Vec[T], pred: fn(&T) -> Bool) -> Bool {
    var i = 0;
    while i < items.len() {
      if !pred(items.get(i).unwrap()) {
        return false;
      };
      i += 1;
    };
    true
  }

  pub fn none_of[T](items: &Vec[T], pred: fn(&T) -> Bool) -> Bool {
    var i = 0;
    while i < items.len() {
      if pred(items.get(i).unwrap()) {
        return false;
      };
      i += 1;
    };
    true
  }
}

fn is_positive(n: &Int) -> Bool { n > 0 }
fn is_smaller(a: &Int, b: &Int) -> Bool { a < b }

fn main() -> Int {
  let nums: Vec[Int] = Vec[Int].new();
  nums.push(5); nums.push(12); nums.push(3);
  let min_val = coll_utils.find_min(&nums, is_smaller).unwrap();
  io.println(min_val.to_str());
  io.println((coll_utils.all_of(&nums, is_positive)).to_str());
  return 0;
}
